:root {
  font-family: system-ui, sans-serif;
  color: #1e293b;
  background: #f4f6fa;
}
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border-radius: 12px; }
h1 { font-size: 2rem; margin: 0 0 28px; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
input[type="text"] { flex: 1; min-width: 0; padding: 10px; border: 1px solid #64748b; border-radius: 6px; font: inherit; }
button { font: inherit; background: #2449ab; color: white; border: 0; border-radius: 6px; padding: 10px 16px; cursor: pointer; }
button:hover { background: #1d3984; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #f59e0b; outline-offset: 3px; }
#projects { margin-top: 28px; }
.project-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 16px 0; border-bottom: 1px solid #e2e8f0; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
.task-filter { margin-top: 28px; }
select { font: inherit; padding: 8px; border: 1px solid #64748b; border-radius: 6px; background: white; }
.task-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 16px 0; border-bottom: 1px solid #e2e8f0; }
.task-row span { overflow-wrap: anywhere; min-width: 0; }
.task-row input { flex-shrink: 0; width: 20px; height: 20px; }
#back { margin-bottom: 24px; }
[role="alert"] { color: #b91c1c; }
[hidden] { display: none !important; }
@media (max-width: 600px) {
  main { margin: 20px 12px; padding: 20px; }
  .create-controls { flex-direction: column; }
}

